-- Explicações por artigo — Lei de Lavagem de Dinheiro (Lei nº 9.613, de 1998). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Lavagem de dinheiro: ocultar ou dissimular a natureza, origem, localização, disposição, movimentação ou propriedade de bens, direitos ou valores provenientes, direta ou indiretamente, de infração penal. Pena: reclusão de três a dez anos e multa. Incorre na mesma pena quem, para ocultar ou dissimular a utilização desses bens, os converte em ativos lícitos; os adquire, recebe, troca, negocia, dá ou recebe em garantia, guarda, tem em depósito, movimenta ou transfere; ou importa ou exporta bens com valores não correspondentes aos verdadeiros. Também quem utiliza na atividade econômica ou financeira bens provenientes de infração penal e quem participa de grupo, associação ou escritório sabendo que sua atividade é dirigida à prática desses crimes. A tentativa é punida. A pena aumenta de 1/3 a 2/3 se os crimes forem cometidos de forma reiterada, por organização criminosa ou por meio de ativo virtual. Há delação premiada: redução, regime aberto ou semiaberto e até perdão judicial para quem colaborar espontaneamente. Admitem-se a ação controlada e a infiltração de agentes.', '["Caput: ocultar ou dissimular bens, direitos ou valores provenientes de infração penal.","Reclusão de três a dez anos e multa.","§1º: conversão em ativos lícitos, aquisição, guarda, movimentação e importação ou exportação com valores falsos.","§2º: uso na atividade econômica e participação em grupo dirigido à lavagem.","§3º: tentativa punida.","§4º: aumento de 1/3 a 2/3 (reiteração, organização criminosa ou ativo virtual).","§5º: delação premiada com redução da pena, regime mais brando ou perdão judicial.","§6º: ação controlada e infiltração de agentes."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 12.683, de 2012, que aboliu o rol taxativo de crimes antecedentes: qualquer infração penal pode ser antecedente (inclusive contravenção).","A lei também previu o ativo virtual no §4º.","Crime acessório: depende de infração penal antecedente, mas é autônomo no processo."]'::jsonb, 'O traficante que compra imóveis em nome de terceiros para esconder a origem do dinheiro comete lavagem.', '["Assertiva que restringe a lavagem a bens provenientes de um rol fechado de crimes erra: após a Lei nº 12.683, de 2012, qualquer infração penal serve."]'::jsonb, '[{"termo":"Infração penal antecedente","significado":"Crime ou contravenção que gerou os bens lavados."}]'::jsonb, '["Art. 2º","Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo e julgamento dos crimes da Lei obedecem ao procedimento comum dos crimes punidos com reclusão, da competência do juiz singular; independem do processo e julgamento das infrações penais antecedentes, ainda que praticados em outro país, cabendo ao juiz competente para a lavagem decidir sobre a unidade de processo e julgamento; e são da competência da Justiça Federal quando praticados contra o sistema financeiro e a ordem econômico-financeira, ou em detrimento de bens, serviços ou interesses da União, ou quando a infração antecedente for de competência federal. A denúncia será instruída com indícios suficientes da existência da infração penal antecedente, sendo puníveis os fatos ainda que o autor seja desconhecido ou isento de pena, ou extinta a punibilidade da infração antecedente.', '["Procedimento comum dos crimes punidos com reclusão, com juiz singular (sem júri).","Autonomia em relação ao processo da infração antecedente.","Justiça Federal: crimes contra o sistema financeiro, a ordem econômico-financeira ou a União, ou antecedente federal.","Denúncia com indícios suficientes da infração antecedente.","Punível mesmo se o autor do antecedente é desconhecido, isento de pena ou com punibilidade extinta."]'::jsonb, '["ATUALIZAÇÃO: redação do inciso II e dos incisos do III dada pela Lei nº 12.683, de 2012.","Basta INDÍCIOS da infração antecedente na denúncia, e não prova plena.","Competência federal depende do caso."]'::jsonb, 'A lavagem do dinheiro de um crime contra a União é julgada pela Justiça Federal.', '["Assertiva que exige condenação prévia pela infração antecedente erra: bastam indícios na denúncia."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz, de ofício, a requerimento do Ministério Público ou mediante representação do delegado de polícia, ouvido o Ministério Público em 24 horas, havendo indícios suficientes de infração penal, poderá decretar medidas assecuratórias de bens, direitos ou valores do investigado ou acusado, ou existentes em nome de interpostas pessoas, que sejam instrumento, produto ou proveito dos crimes da Lei ou das infrações antecedentes. Procede-se à alienação antecipada quando os bens estiverem sujeitos a deterioração ou depreciação ou houver dificuldade para sua manutenção. O juiz liberará os bens quando comprovada a licitude de sua origem, mantendo os necessários à reparação dos danos e ao pagamento de multas e custas. Nenhum pedido de liberação será conhecido sem o comparecimento pessoal do acusado ou de interposta pessoa.', '["Medidas assecuratórias: sequestro e outras, de ofício, a pedido do MP ou por representação do delegado.","Alcança bens em nome de interpostas pessoas (laranjas).","Alienação antecipada em caso de deterioração ou dificuldade de manutenção.","Liberação se comprovada a origem lícita.","Pedido de liberação exige comparecimento pessoal do acusado.","§4º: medidas para reparar o dano ou pagar prestação pecuniária, multa e custas."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 12.683, de 2012.","O MP é ouvido em 24 horas.","O PEDIDO DE LIBERAÇÃO exige a presença do acusado ou da interposta pessoa."]'::jsonb, 'O juiz bloqueia imóveis registrados em nome de um laranja do investigado.', '["Assertiva que permite a liberação dos bens sem comparecimento pessoal erra: ele é exigido."]'::jsonb, '[{"termo":"Interposta pessoa","significado":"Quem figura como dono dos bens para esconder o verdadeiro proprietário."}]'::jsonb, '["Art. 4º-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A alienação antecipada para preservação de valor de bens sob constrição é decretada pelo juiz, de ofício, a requerimento do Ministério Público ou por solicitação da parte interessada, por petição autônoma, em autos apartados. O requerimento deve relacionar os bens e quem os detém. O juiz determina a avaliação, intima o Ministério Público e, por sentença, homologa o valor e manda alienar em leilão ou pregão, preferencialmente eletrônico, por valor não inferior a 75% da avaliação. A quantia é depositada em conta judicial remunerada: na Justiça Federal, na Caixa Econômica Federal ou instituição pública, com repasse à Conta Única do Tesouro em 24 horas; nos Estados e no Distrito Federal, em instituição financeira designada em lei. Após o trânsito em julgado, o valor é incorporado ao patrimônio da União ou do ente federativo (condenação) ou devolvido ao réu com a remuneração (absolvição extintiva de punibilidade). Os recursos têm apenas efeito devolutivo. Com a condenação, decreta-se a perda dos valores, da fiança, dos bens não alienados e dos bens não reclamados em 90 dias.', '["Petição autônoma e autos em apartado.","Leilão por valor não inferior a 75% da avaliação.","Depósito em conta judicial remunerada.","Condenação: valor incorporado à União, Estado ou DF.","Absolvição: valor devolvido ao réu com remuneração.","Recursos só com efeito devolutivo.","Perda de bens não reclamados em 90 dias."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 12.683, de 2012.","Piso do leilão: 75% da avaliação."]'::jsonb, 'Carros apreendidos que se deterioram são leiloados antecipadamente e o valor fica em conta judicial.', '["Assertiva que permite o leilão por qualquer valor erra: o piso é de 75% da avaliação."]'::jsonb, '[{"termo":"Efeito devolutivo","significado":"O recurso devolve a matéria ao tribunal, sem suspender a decisão."}]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-4-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A ordem de prisão de pessoas ou as medidas assecuratórias de bens, direitos ou valores poderão ser suspensas pelo juiz, ouvido o Ministério Público, quando a sua execução imediata puder comprometer as investigações.', '["Suspensão da ordem de prisão ou das medidas assecuratórias.","Quando a execução imediata puder comprometer as investigações.","Ouvido o Ministério Público."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 12.683, de 2012.","Espécie de ação controlada: retarda a execução para não frustrar a investigação."]'::jsonb, 'O juiz adia o bloqueio de contas para não alertar a quadrilha durante a investigação.', '["Assertiva que dispensa a oitiva do Ministério Público para a suspensão erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-4-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando as circunstâncias o aconselharem, o juiz, ouvido o Ministério Público, nomeará pessoa física ou jurídica qualificada para a administração dos bens, direitos ou valores sujeitos a medidas assecuratórias, mediante termo de compromisso.', '["Nomeação de administrador qualificado, pessoa física ou jurídica.","Ouvido o Ministério Público.","Termo de compromisso."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 12.683, de 2012.","Nomeação quando as circunstâncias aconselharem."]'::jsonb, 'O juiz nomeia uma empresa especializada para administrar uma fazenda bloqueada.', '["Assertiva que torna obrigatória a nomeação de administrador em todos os casos erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pessoa responsável pela administração dos bens fará jus a uma remuneração, fixada pelo juiz, satisfeita com o produto dos bens administrados, e prestará, por determinação judicial, informações periódicas sobre a situação dos bens e sobre investimentos e reinvestimentos realizados. Os atos de administração serão levados ao conhecimento do Ministério Público, que requererá o que entender cabível.', '["Remuneração fixada pelo juiz, paga com o produto dos bens.","Prestação de informações periódicas.","Atos levados ao conhecimento do Ministério Público."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 12.683, de 2012."]'::jsonb, 'O administrador presta contas periódicas ao juiz sobre os bens bloqueados.', '["Assertiva que fixa a remuneração do administrador com recursos do Estado erra: ela sai dos bens administrados."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'São efeitos da condenação, além dos previstos no Código Penal: a perda, em favor da União (ou dos Estados e do Distrito Federal, nos casos da Justiça Estadual), de todos os bens, direitos e valores relacionados à prática dos crimes da Lei, inclusive os usados para prestar a fiança, ressalvado o direito do lesado ou de terceiro de boa-fé; e a interdição do exercício de cargo ou função pública e de diretor, membro de conselho de administração ou gerência das pessoas jurídicas do art. 9º, pelo dobro do tempo da pena privativa de liberdade aplicada. Os entes regulamentarão a destinação dos bens, assegurada a utilização pelos órgãos encarregados da prevenção e do combate. Os instrumentos do crime sem valor econômico serão inutilizados ou doados a museu criminal ou a entidade pública.', '["Perda de bens, direitos e valores ligados ao crime, em favor da União, Estados ou DF.","Ressalva do lesado e do terceiro de boa-fé.","Interdição de cargo, função pública e direção de pessoas jurídicas do art. 9º pelo dobro da pena.","Destinação dos bens regulamentada pelos entes.","Instrumentos sem valor: inutilização ou doação."]'::jsonb, '["ATUALIZAÇÃO: inciso I com redação da Lei nº 15.358, de 2026.","A interdição dura o DOBRO do tempo da pena privativa de liberdade."]'::jsonb, 'O condenado por lavagem perde os imóveis ligados ao crime, e o terceiro de boa-fé é ressalvado.', '["Assertiva que fixa a interdição pelo mesmo tempo da pena erra: é pelo dobro."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz determinará, na hipótese de existência de tratado ou convenção internacional e por solicitação de autoridade estrangeira competente, medidas assecuratórias sobre bens, direitos ou valores oriundos de crimes descritos no art. 1º praticados no estrangeiro. Aplica-se o dispositivo, independentemente de tratado, quando o governo do país solicitante prometer reciprocidade ao Brasil. Na falta de tratado ou convenção, os bens privados sujeitos a medidas assecuratórias ou os recursos da alienação serão repartidos entre o Estado requerente e o Brasil, na proporção de metade, ressalvado o direito do lesado ou de terceiro de boa-fé.', '["Medidas assecuratórias a pedido de autoridade estrangeira, com tratado ou convenção.","Sem tratado, basta a promessa de reciprocidade.","Repartição de metade entre o Estado requerente e o Brasil.","Ressalva do lesado e do terceiro de boa-fé."]'::jsonb, '["ATUALIZAÇÃO: caput e §2º com redação da Lei nº 12.683, de 2012.","Reciprocidade substitui o tratado."]'::jsonb, 'O Brasil bloqueia valores a pedido de outro país que prometeu reciprocidade.', '["Assertiva que exige sempre tratado para a cooperação erra: basta a promessa de reciprocidade."]'::jsonb, '[{"termo":"Reciprocidade","significado":"Promessa de tratar o outro país da mesma forma em casos semelhantes."}]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-8'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Sujeitam-se às obrigações dos arts. 10 e 11 as pessoas físicas e jurídicas que tenham, em caráter permanente ou eventual, como atividade principal ou acessória, a captação, intermediação e aplicação de recursos financeiros de terceiros; a compra e venda de moeda estrangeira ou ouro como ativo financeiro; e a custódia, emissão, distribuição, negociação ou administração de títulos ou valores mobiliários. O parágrafo único estende a obrigação a bolsas, seguradoras, administradoras de cartões e consórcios, empresas de arrendamento mercantil, factoring, e outras atividades, como promoção imobiliária, comércio de joias e bens de luxo e de arte, entre outras.', '["Setor financeiro: captação, intermediação e aplicação de recursos de terceiros.","Compra e venda de moeda estrangeira ou ouro.","Custódia e negociação de valores mobiliários.","Estendido a bolsas, seguradoras, cartões, consórcios, leasing, factoring e outros setores."]'::jsonb, '["ATUALIZAÇÃO: redação dada pela Lei nº 12.683, de 2012.","São os chamados SETORES OBRIGADOS (compliance)."]'::jsonb, 'Uma corretora de valores é obrigada a identificar clientes e comunicar operações suspeitas.', '["Assertiva que restringe as obrigações aos bancos erra: abrangem vários setores."]'::jsonb, '[{"termo":"Pessoas obrigadas","significado":"Setores sujeitos ao cadastro e à comunicação de operações ao Coaf."}]'::jsonb, '["Art. 10","Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-9'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As pessoas referidas no art. 9º identificarão seus clientes e manterão cadastro atualizado; manterão registro de toda transação em moeda nacional ou estrangeira, títulos, metais, ativos virtuais ou qualquer ativo conversível em dinheiro que ultrapasse o limite fixado pela autoridade; adotarão políticas, procedimentos e controles internos compatíveis com seu porte; cadastrar-se-ão no órgão regulador ou, na falta, no Coaf; e atenderão às requisições do Coaf, preservando o sigilo das informações.', '["Identificação de clientes e cadastro atualizado.","Registro de transações acima do limite.","Políticas e controles internos.","Cadastro no órgão regulador ou no Coaf.","Atendimento às requisições do Coaf."]'::jsonb, '["ATUALIZAÇÃO: inciso II com redação da Lei nº 14.478, de 2022 (ativos virtuais); incisos III a V com redação da Lei nº 12.683, de 2012."]'::jsonb, 'A concessionária de joias mantém cadastro de clientes e registra vendas acima do limite.', '["Assertiva que dispensa o registro de transações com ativos virtuais erra: foram incluídas pela Lei nº 14.478, de 2022."]'::jsonb, '[]'::jsonb, '["Art. 9º","Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-10'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Banco Central manterá registro centralizado formando o cadastro geral de correntistas e clientes de instituições financeiras, bem como de seus procuradores.', '["Banco Central mantém o cadastro geral de correntistas e clientes.","Inclui os procuradores."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 10.701, de 2003 (CCS)."]'::jsonb, 'A autoridade consulta o cadastro do Banco Central para saber em que bancos o investigado tem contas.', '["Assertiva que atribui o cadastro geral de correntistas ao Coaf erra: é do Banco Central."]'::jsonb, '[]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
