insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As pessoas do art. 9º dispensarão especial atenção às operações que possam constituir sérios indícios dos crimes da Lei; deverão comunicar ao Coaf, abstendo-se de dar ciência a qualquer pessoa, inclusive àquela a quem se refira a informação, no prazo de 24 horas, a proposta ou realização das transações acima do limite e das operações suspeitas; e comunicarão ao órgão regulador ou ao Coaf a não ocorrência de operações passíveis de comunicação. As autoridades elaborarão relação de operações suspeitas. As comunicações de boa-fé não acarretam responsabilidade civil ou administrativa. O Coaf disponibiliza as comunicações aos órgãos reguladores.', '["Atenção especial a operações suspeitas.","Comunicação ao Coaf em 24 horas, sem avisar o cliente.","Comunicação negativa quando não houver operações.","Boa-fé: sem responsabilidade civil ou administrativa."]'::jsonb, '["ATUALIZAÇÃO: incisos II e III com redação da Lei nº 12.683, de 2012.","Prazo de 24 horas.","Sigilo: NÃO se avisa o cliente."]'::jsonb, 'O banco comunica ao Coaf, em 24 horas, uma movimentação atípica, sem avisar o cliente.', '["Assertiva que obriga a avisar o cliente da comunicação ao Coaf erra: é vedado."]'::jsonb, '[{"termo":"Coaf","significado":"Conselho de Controle de Atividades Financeiras."}]'::jsonb, '["Art. 9º","Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-11'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'As transferências internacionais e os saques em espécie deverão ser previamente comunicados à instituição financeira, nos termos, limites, prazos e condições fixados pelo Banco Central do Brasil.', '["Transferências internacionais e saques em espécie.","Comunicação prévia à instituição financeira.","Regras fixadas pelo Banco Central."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 12.683, de 2012."]'::jsonb, 'Quem fará um grande saque em dinheiro avisa antes a instituição financeira.', '["Assertiva que dispensa o aviso prévio em saques em espécie erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-11-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Às pessoas do art. 9º e a seus administradores que deixem de cumprir os arts. 10 e 11 serão aplicadas, cumulativamente ou não, as sanções de advertência; multa pecuniária variável não superior ao dobro do valor da operação, ao dobro do lucro real obtido ou que seria obtido, ou a vinte milhões de reais; inabilitação temporária, por até dez anos, para o cargo de administrador; e cassação ou suspensão da autorização para a atividade. A advertência aplica-se por irregularidade no cumprimento das instruções dos incisos I e II do art. 10. A multa será aplicada sempre que, por culpa ou dolo, deixarem de sanar irregularidades objeto de advertência, não realizarem a identificação ou o registro, deixarem de atender requisição do Coaf, ou descumprirem a vedação de comunicar o cliente. A inabilitação exige infrações graves ou reincidência específica, e a cassação exige reincidência específica.', '["Sanções: advertência, multa, inabilitação e cassação.","Multa limitada pelo dobro da operação, dobro do lucro ou vinte milhões de reais.","Inabilitação de até dez anos.","Cassação da autorização em reincidência específica."]'::jsonb, '["ATUALIZAÇÃO: incisos II e IV com redação da Lei nº 12.683, de 2012 (multa de vinte milhões de reais).","Sanções ADMINISTRATIVAS aplicadas pelas autoridades competentes."]'::jsonb, 'O banco que não comunica operação suspeita ao Coaf sofre multa e outras sanções administrativas.', '["Assertiva que trata essas sanções como penas criminais erra: são administrativas."]'::jsonb, '[]'::jsonb, '["Art. 10","Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-12'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ato do Poder Executivo federal regulamentará a disciplina e o funcionamento do Cadastro Nacional de Pessoas Expostas Politicamente (CNPEP), disponibilizado pelo Portal da Transparência. Os órgãos e entidades de todos os Poderes e entes encaminharão ao gestor do cadastro informações atualizadas sobre seus integrantes classificados como pessoas expostas politicamente. As pessoas do art. 9º incluirão consulta ao CNPEP entre seus procedimentos. O órgão gestor indicará pela internet os órgãos que deixem de cumprir a obrigação.', '["Cadastro Nacional de Pessoas Expostas Politicamente (CNPEP).","Órgãos públicos devem informar seus PEPs.","Setores obrigados consultam o CNPEP.","Transparência ativa sobre quem não cumprir."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 14.478, de 2022; o texto indica status de vigência a verificar."]'::jsonb, 'Antes de abrir conta para um agente público, o banco consulta o CNPEP.', '["Assertiva que dispensa a consulta ao CNPEP pelos setores obrigados erra."]'::jsonb, '[{"termo":"PEP","significado":"Pessoa exposta politicamente."}]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-12-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É criado, no âmbito do Ministério da Fazenda, o Conselho de Controle de Atividades Financeiras (Coaf), com a finalidade de disciplinar, aplicar penas administrativas, receber, examinar e identificar as ocorrências suspeitas de atividades ilícitas previstas na Lei, sem prejuízo da competência de outros órgãos. As instruções do art. 10 para as pessoas sem órgão fiscalizador próprio serão expedidas pelo Coaf. O Coaf coordenará a cooperação e a troca de informações e poderá requerer aos órgãos da Administração Pública as informações cadastrais bancárias e financeiras de pessoas envolvidas em atividades suspeitas.', '["Coaf: unidade de inteligência financeira.","Disciplina, aplica penas administrativas, recebe, examina e identifica ocorrências suspeitas.","Expede instruções para quem não tem regulador próprio.","Coordena cooperação e troca de informações."]'::jsonb, '["ATUALIZAÇÃO: §3º incluído pela Lei nº 10.701, de 2003.","O Coaf NÃO investiga nem acusa: produz relatórios de inteligência."]'::jsonb, 'O Coaf identifica movimentações suspeitas e comunica as autoridades competentes.', '["Assertiva que atribui ao Coaf a função de promover a ação penal erra."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lavagem' and u.unit_key = 'art-14'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Coaf comunicará às autoridades competentes para a instauração dos procedimentos cabíveis, quando concluir pela existência de crimes previstos na Lei, de fundados indícios de sua prática, ou de qualquer outro ilícito.', '["Comunicação às autoridades competentes.","Quando houver crime, fundados indícios ou qualquer outro ilícito."]'::jsonb, '["A comunicação (relatório de inteligência financeira) não é prova em si, mas pode dar origem à investigação."]'::jsonb, 'O Coaf envia relatório à Polícia Federal sobre movimentação atípica.', '["Assertiva que restringe a comunicação do Coaf aos crimes da Lei erra: vale para qualquer ilícito."]'::jsonb, '[]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
